layer.css:
@import url("https://fonts.googleapis.com/css2?family=Lato&family=Lobster+Two&family=Patua+One&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgba(0, 0, 0, 0.024); border-left: 4px solid rgb(105, 99, 73); border-radius: 0px 6px 6px 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 18.4px; padding-right: 24px; padding-bottom: 18.4px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 0px; transition: all; border-top: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-bg); background-color: rgb(140, 21, 21); border-radius: 800px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4.48px; padding-right: 8.32px; padding-bottom: 4.48px; padding-left: 8.32px; transition: all }
[data-ryt="section"] > h2 { color: rgb(140, 21, 21); border-radius: 0px; font-family: "Lobster Two", serif; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(140, 21, 21); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-bg); background-color: rgb(105, 99, 73); border-radius: 4px; font-family: "Lobster Two", serif; font-size: 20px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(105, 99, 73); border-radius: 6px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out }
[data-ryt="review"] { color: color-mix(in srgb, var(--ryt-muted) 75%, transparent); font-family: var(--ryt-font-heading); font-size: 13.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-muted) 75%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: color-mix(in srgb, var(--ryt-muted) 75%, transparent); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-muted) 75%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #003d82 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #003d82 }
[data-ryt="button"]:hover { color: initial; background-color: initial; color: #ffffff; background-color: color-mix(in srgb, var(--ryt-bg) 15%, transparent); color: #ffffff; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-color: #696349; text-decoration-style: dotted; background-color: #696349; opacity: 0.85; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { color: #003d82 }
[data-ryt="brand"]:hover { color: #ffffff; color: #ffffff; opacity: 0.85 }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { opacity: 0.85; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #ffffff }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #003d82 }
